CREATE DATABASE IF NOT EXISTS karakata CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE karakata;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(40) NULL,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE products (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,title VARCHAR(150) NOT NULL,description TEXT NOT NULL,price DECIMAL(14,2) NOT NULL,location VARCHAR(160) NOT NULL,category VARCHAR(80) NOT NULL,condition_type ENUM('Used','Brand New') NOT NULL,image VARCHAR(255) NULL,status ENUM('active','sold') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(status,created_at),INDEX(category),CONSTRAINT fk_product_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE conversations (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id INT UNSIGNED NOT NULL,buyer_id INT UNSIGNED NOT NULL,seller_id INT UNSIGNED NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY unique_chat(product_id,buyer_id,seller_id),CONSTRAINT fk_chat_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,CONSTRAINT fk_chat_buyer FOREIGN KEY(buyer_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_chat_seller FOREIGN KEY(seller_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE messages (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,conversation_id INT UNSIGNED NOT NULL,sender_id INT UNSIGNED NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(conversation_id,created_at),CONSTRAINT fk_message_chat FOREIGN KEY(conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,CONSTRAINT fk_message_sender FOREIGN KEY(sender_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
